import{$ as e,H as t,_t as n,at as r,it as i,nt as a,rt as o,xt as s}from"./chunks/framework.B6hMYkVh.js";import"./chunks/assets.C264fkKD.js";var c=JSON.parse(`{"title":"AI Agent","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/ai-agent.md","filePath":"reporting/ai-agent.md","lastUpdated":1789046697000}`),l={name:`reporting/ai-agent.md`};function u(t,c,l,u,d,f){let p=s(`BadgePro`);return n(),a(`div`,null,[c[4]||=o(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /reporting/ai-agent.md for this page in Markdown format</div><h1 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to “AI Agent”">​</a></h1><p>The AI agent assists with pentest report writing and analysis. It can answer questions about your project, suggest and review content, create and edit findings and sections.</p><p>To be able to use the agent, enable it in applications settings and configure an LLM provider (see <a href="/setup/configuration#ai-agent">configuration</a>). Multiple LLM providers and also self-hosted models are supported.</p><p><img src="/images/ai-agent.png" alt="AI agent" width="1167" height="651" loading="lazy"></p><p>The agent has access to project data through context and tools.</p><h2 id="project-scoping" tabindex="-1">Project scoping <a class="header-anchor" href="#project-scoping" aria-label="Permalink to “Project scoping”">​</a></h2><p>The SysReptor AI agent is bound to the <strong>current pentest project</strong> only.</p><p>It <strong>can</strong>:</p><ul><li>Read that project&#39;s structure, report sections, findings, notes, and the project&#39;s design field definitions</li><li>See which section, finding, or note you currently have open in the UI</li><li>Search <strong>finding templates</strong> in the instance knowledge base (templates are shared, not limited to one project)</li></ul><p>It <strong>cannot</strong>:</p><ul><li>Read or edit <strong>other projects</strong></li><li>Access other users&#39; private data, instance admin settings, or findings and notes that belong to a different project</li></ul><h2 id="agent-mode" tabindex="-1">Agent Mode <a class="header-anchor" href="#agent-mode" aria-label="Permalink to “Agent Mode”">​</a></h2>`,13),e(`ul`,null,[c[3]||=e(`li`,null,[e(`strong`,null,`Ask`),i(`: Read-only. The agent can view the project and answer questions or suggest text. It does not create or edit any data; you copy and apply suggestions yourself.`)],-1),e(`li`,null,[c[0]||=e(`strong`,null,`Agent`,-1),c[1]||=i(` (`,-1),r(p),c[2]||=i(`): Full write access in this project. In addition to everything in Ask mode, the agent can create findings and notes and update section, finding, and note fields.`,-1)])]),c[5]||=o(`<h2 id="asking-clarifying-questions" tabindex="-1">Asking clarifying questions <a class="header-anchor" href="#asking-clarifying-questions" aria-label="Permalink to “Asking clarifying questions”">​</a></h2><p>When information is missing or there are multiple valid approaches, the agent can pause and ask you a multiple-choice question. Pick an option (or type your own answer) to continue, or send a new message to skip the question.</p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to “AGENTS.md”">​</a></h2><p>You can give the agent reusable instructions with an <code>AGENTS.md</code> note:</p><p><img src="/images/agent-agentsmd.png" alt=" in project notes" width="200" height="138" loading="lazy"></p><p>Place a <code>.agents</code> folder note at the root of the project notes tree, then add a child note titled <code>AGENTS.md</code>. Put your guidance in the note text as markdown e.g. tone, conventions, what to prioritize, and other project-specific instructions.</p><p>The full contents of <code>AGENTS.md</code> are loaded into the agent&#39;s system message at the start of every chat. Edits may not apply until you start a new chat. Edit the note in the notes UI.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to “Skills”">​</a></h2><p>For specialized, on-demand workflows you can add <a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">Agent Skills</a> under the same <code>.agents</code> tree. Skills differ from <code>AGENTS.md</code>: only a short catalog is always visible; full instructions are loaded later, and only if the model decides a skill fits the task. See the agentskills.io guides on <a href="https://agentskills.io/skill-creation/best-practices" target="_blank" rel="noreferrer">writing skills</a> and <a href="https://agentskills.io/skill-creation/optimizing-descriptions" target="_blank" rel="noreferrer">optimizing descriptions</a> for how to structure effective skills.</p><p><img src="/images/agent-skills.png" alt="Agent skills" width="366" height="539" loading="lazy"></p><p>Each skill is a folder note under <code>skills</code> with a child note titled exactly <code>SKILL.md</code>. Put the skill frontmatter and instructions in the <code>SKILL.md</code> note body (markdown), for example:</p><div class="language-md line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-skill</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Tells the agent when to use this skill. </span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  This is how the agent decides whether to activate it.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># My skill</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Instructions the agent follows when the skill activates</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>At the start of a chat the agent only sees each skill&#39;s name and description (from the catalog). It reads the full <code>SKILL.md</code> (and any supporting notes) only when it chooses to use that skill. A skill might not be picked up even if it would help. The LLM decides based on the description and the user&#39;s request.</p><div class="tip custom-block"><p class="custom-block-title">How to improve skill descriptions</p><p>See <a href="https://agentskills.io/skill-creation/optimizing-descriptions" target="_blank" rel="noreferrer">Optimizing skill descriptions</a>.</p></div><p>Optional sibling notes and nested notes under the skill folder are available as markdown files the agent can read (for example <code>references.md</code> or <code>references/api.md</code>). Scripts, binaries, and other non-note resources are not supported.</p><p>The skill catalog is loaded when the thread starts; new or changed skills may not appear until you start a new chat. Skill notes are normal notes: edit them in the notes UI.</p><h2 id="example-use-cases" tabindex="-1">Example Use Cases <a class="header-anchor" href="#example-use-cases" aria-label="Permalink to “Example Use Cases”">​</a></h2><ul><li>Generate executive summary from findings</li><li>Generate finding recommendation from technical description</li><li>Review texts for grammar and spelling</li><li>Create findings from notes</li><li>Analyze the report and ask questions about it</li><li>and much more</li></ul>`,18)])}var d=t(l,[[`render`,u]]);export{c as __pageData,d as default};